ALTER TABLE public.user_roles ADD COLUMN staff_name text NOT NULL DEFAULT '', ADD COLUMN staff_code text NOT NULL DEFAULT '', ADD COLUMN tl_id uuid;
CREATE TABLE public.admin_tl_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_id uuid NOT NULL, tl_id uuid NOT NULL, UNIQUE(admin_id,tl_id));
GRANT SELECT ON public.admin_tl_assignments TO authenticated; GRANT ALL ON public.admin_tl_assignments TO service_role;
ALTER TABLE public.admin_tl_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY assignment_read ON public.admin_tl_assignments FOR SELECT TO authenticated USING(admin_id=auth.uid() OR tl_id=auth.uid() OR public.has_role(auth.uid(),'it'));
CREATE FUNCTION public.validate_staff_links() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='admin_tl_assignments' THEN PERFORM pg_advisory_xact_lock(hashtext(NEW.admin_id::text)); IF NOT public.has_role(NEW.admin_id,'adm') OR NOT public.has_role(NEW.tl_id,'tl') THEN RAISE EXCEPTION 'Assignment requires ADM and TL accounts'; END IF; IF (SELECT count(*) FROM public.admin_tl_assignments WHERE admin_id=NEW.admin_id AND id<>NEW.id)>=2 THEN RAISE EXCEPTION 'One ADM may manage at most two TL accounts'; END IF; ELSE IF NEW.tl_id IS NOT NULL AND (NEW.role<>'se' OR NOT public.has_role(NEW.tl_id,'tl')) THEN RAISE EXCEPTION 'SE supervisor must be a TL'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_staff_links() FROM PUBLIC;
CREATE TRIGGER validate_admin_tl BEFORE INSERT OR UPDATE ON public.admin_tl_assignments FOR EACH ROW EXECUTE FUNCTION public.validate_staff_links();
CREATE TRIGGER validate_se_tl BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.validate_staff_links();
CREATE POLICY it_role_read ON public.user_roles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'it'));
CREATE FUNCTION public.staff_directory() RETURNS TABLE(user_id uuid,role public.app_role,staff_name text,staff_code text,tl_id uuid,team_id uuid,project_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.user_id,s.role,s.staff_name,s.staff_code,s.tl_id,s.team_id,s.project_id FROM public.user_roles s JOIN public.user_roles r ON r.user_id=auth.uid() WHERE s.user_id=r.user_id OR r.role IN ('it','dir') OR (r.role='sm' AND r.project_id IS NOT NULL AND s.project_id=r.project_id) OR (r.role='tl' AND (s.tl_id=r.user_id OR s.user_id=r.user_id)) OR (r.role='adm' AND EXISTS(SELECT 1 FROM public.admin_tl_assignments a WHERE a.admin_id=r.user_id AND (s.user_id=a.tl_id OR s.tl_id=a.tl_id))); $$;
REVOKE ALL ON FUNCTION public.staff_directory() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.staff_directory() TO authenticated;
CREATE OR REPLACE FUNCTION public.feature_access(_feature text,_write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND (r.role='it' OR CASE _feature WHEN 'team' THEN r.role IN ('tl','sm','dir') WHEN 'verification' THEN CASE WHEN _write THEN r.role='adm' ELSE r.role IN ('adm','sm') END WHEN 'content' THEN CASE WHEN _write THEN r.role='dm' ELSE r.role IN ('dm','sm','dir') END WHEN 'projects' THEN CASE WHEN _write THEN r.role IN ('tl','sm') ELSE r.role IN ('tl','sm','dir') END WHEN 'portfolio' THEN r.role='dir' ELSE false END)); $$;
CREATE TABLE public.sales_projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),target_amount numeric NOT NULL DEFAULT 0 CHECK(target_amount>=0),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.sales_projects TO authenticated; GRANT ALL ON public.sales_projects TO service_role; ALTER TABLE public.sales_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY project_read ON public.sales_projects FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND (r.role IN ('it','dir') OR r.project_id=id OR created_by=r.user_id)));
CREATE POLICY project_create ON public.sales_projects FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND (public.has_role(auth.uid(),'tl') OR public.has_role(auth.uid(),'sm')));
CREATE OR REPLACE FUNCTION public.can_read_scope(_owner uuid,_team uuid,_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND (r.user_id=_owner OR r.role IN ('it','dir') OR (r.role='tl' AND ((r.team_id IS NOT NULL AND r.team_id=_team) OR EXISTS(SELECT 1 FROM public.user_roles s WHERE s.user_id=_owner AND s.tl_id=r.user_id))) OR (r.role='adm' AND EXISTS(SELECT 1 FROM public.admin_tl_assignments a JOIN public.user_roles t ON t.user_id=a.tl_id LEFT JOIN public.user_roles s ON s.user_id=_owner WHERE a.admin_id=r.user_id AND (s.tl_id=t.user_id OR _owner=t.user_id OR (t.team_id IS NOT NULL AND t.team_id=_team)))) OR (r.role IN ('sm','dm') AND r.project_id IS NOT NULL AND r.project_id=_project) OR (r.role='sm' AND EXISTS(SELECT 1 FROM public.sales_projects p WHERE p.id=_project AND p.created_by=r.user_id)))); $$;
CREATE FUNCTION public.valid_owner_scope(_owner uuid,_team uuid,_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.user_id=_owner AND _team IS NOT DISTINCT FROM r.team_id AND (_project IS NOT DISTINCT FROM r.project_id OR (r.role IN ('tl','sm') AND EXISTS(SELECT 1 FROM public.sales_projects p WHERE p.id=_project AND p.created_by=r.user_id)))); $$;
REVOKE ALL ON FUNCTION public.valid_owner_scope(uuid,uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.valid_owner_scope(uuid,uuid,uuid) TO authenticated;
CREATE TABLE public.sales_leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nickname text NOT NULL CHECK(length(nickname) BETWEEN 1 AND 200),owner_id uuid NOT NULL,team_id uuid,project_id uuid REFERENCES public.sales_projects(id),status text NOT NULL DEFAULT 'LEAD' CHECK(status IN ('NA','NO','ENG','LEAD','QL','HOT','VISIT','BOOK','CV','NURTURE','LOST')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.sales_leads TO authenticated; GRANT ALL ON public.sales_leads TO service_role; ALTER TABLE public.sales_leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY lead_read ON public.sales_leads FOR SELECT TO authenticated USING(NOT public.has_role(auth.uid(),'dm') AND public.can_read_scope(owner_id,team_id,project_id));
CREATE POLICY lead_write ON public.sales_leads FOR INSERT TO authenticated WITH CHECK((public.has_role(auth.uid(),'se') OR public.has_role(auth.uid(),'tl') OR public.has_role(auth.uid(),'sm')) AND public.valid_owner_scope(owner_id,team_id,project_id));
CREATE POLICY lead_update ON public.sales_leads FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(public.valid_owner_scope(owner_id,team_id,project_id));
CREATE TABLE public.sales_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid REFERENCES public.sales_leads(id),owner_id uuid NOT NULL,team_id uuid,project_id uuid NOT NULL REFERENCES public.sales_projects(id),amount numeric NOT NULL CHECK(amount>=0),status text NOT NULL CHECK(status IN ('BOOK','CV','CANCELLED')),closed_on date NOT NULL DEFAULT current_date,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.sales_transactions TO authenticated; GRANT ALL ON public.sales_transactions TO service_role; ALTER TABLE public.sales_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY transaction_read ON public.sales_transactions FOR SELECT TO authenticated USING(NOT public.has_role(auth.uid(),'dm') AND public.can_read_scope(owner_id,team_id,project_id));
CREATE TABLE public.sales_activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,team_id uuid,project_id uuid REFERENCES public.sales_projects(id),kind text NOT NULL CHECK(kind IN ('Posting','Chat','Call','D2D','Tur','Open table')),note text NOT NULL DEFAULT '',occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.sales_activities TO authenticated; GRANT ALL ON public.sales_activities TO service_role; ALTER TABLE public.sales_activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_read ON public.sales_activities FOR SELECT TO authenticated USING(NOT public.has_role(auth.uid(),'dm') AND public.can_read_scope(owner_id,team_id,project_id));
CREATE POLICY activity_create ON public.sales_activities FOR INSERT TO authenticated WITH CHECK((public.has_role(auth.uid(),'se') OR public.has_role(auth.uid(),'tl')) AND public.valid_owner_scope(owner_id,team_id,project_id));
CREATE TABLE public.ai_videos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,asset_url text CHECK(asset_url IS NULL OR asset_url LIKE 'https://%'),owner_id uuid NOT NULL,team_id uuid,project_id uuid REFERENCES public.sales_projects(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')),publisher_id uuid,tl_id uuid,published_at timestamptz,CHECK(status<>'published' OR (publisher_id IS NOT NULL AND tl_id IS NOT NULL AND published_at IS NOT NULL)),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_videos TO authenticated; GRANT ALL ON public.ai_videos TO service_role; ALTER TABLE public.ai_videos ENABLE ROW LEVEL SECURITY;
CREATE POLICY video_read ON public.ai_videos FOR SELECT TO authenticated USING(public.can_read_scope(owner_id,team_id,project_id));
CREATE FUNCTION public.validate_video_publication() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='published' AND NOT EXISTS(SELECT 1 FROM public.user_roles s JOIN public.user_roles t ON t.user_id=NEW.tl_id WHERE s.user_id=NEW.publisher_id AND s.role='se' AND t.role='tl' AND s.tl_id=t.user_id) THEN RAISE EXCEPTION 'Publication requires an SE and their assigned TL'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_video_publication() FROM PUBLIC;
CREATE TRIGGER video_publication_check BEFORE INSERT OR UPDATE ON public.ai_videos FOR EACH ROW EXECUTE FUNCTION public.validate_video_publication();
CREATE TABLE public.calendar_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL DEFAULT auth.uid(),team_id uuid,project_id uuid REFERENCES public.sales_projects(id),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200),kind text NOT NULL CHECK(kind IN ('survey','tour','follow_up')),starts_at timestamptz NOT NULL,location text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','done','cancelled')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.calendar_events TO authenticated; GRANT ALL ON public.calendar_events TO service_role; ALTER TABLE public.calendar_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_read ON public.calendar_events FOR SELECT TO authenticated USING(public.can_read_scope(owner_id,team_id,project_id));
CREATE POLICY event_create ON public.calendar_events FOR INSERT TO authenticated WITH CHECK(public.valid_owner_scope(owner_id,team_id,project_id));
CREATE POLICY event_update ON public.calendar_events FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(public.valid_owner_scope(owner_id,team_id,project_id));
CREATE TABLE public.event_reminders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES public.calendar_events(id),recipient_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('h_minus_1','day_of')),created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz,UNIQUE(event_id,recipient_id,kind));
GRANT SELECT,UPDATE ON public.event_reminders TO authenticated; GRANT ALL ON public.event_reminders TO service_role; ALTER TABLE public.event_reminders ENABLE ROW LEVEL SECURITY;
CREATE POLICY reminder_read ON public.event_reminders FOR SELECT TO authenticated USING(recipient_id=auth.uid() OR public.has_role(auth.uid(),'it'));
CREATE POLICY reminder_seen ON public.event_reminders FOR UPDATE TO authenticated USING(recipient_id=auth.uid()) WITH CHECK(recipient_id=auth.uid());
REVOKE UPDATE ON public.event_reminders FROM authenticated; GRANT UPDATE(read_at) ON public.event_reminders TO authenticated;
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid,action text NOT NULL,record_id uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_it_read ON public.audit_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'it'));
CREATE FUNCTION public.audit_revision_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,action,record_id) VALUES(auth.uid(),TG_TABLE_NAME||':'||TG_OP,NEW.id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.audit_revision_changes() FROM PUBLIC;
CREATE TRIGGER audit_project AFTER INSERT ON public.sales_projects FOR EACH ROW EXECUTE FUNCTION public.audit_revision_changes();
CREATE TRIGGER audit_event AFTER INSERT OR UPDATE ON public.calendar_events FOR EACH ROW EXECUTE FUNCTION public.audit_revision_changes();
CREATE TRIGGER audit_assignment AFTER INSERT OR UPDATE ON public.admin_tl_assignments FOR EACH ROW EXECUTE FUNCTION public.audit_revision_changes();
CREATE TRIGGER audit_role AFTER INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.audit_revision_changes();
CREATE FUNCTION public.generate_event_reminders() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.event_reminders(event_id,recipient_id,kind) SELECT e.id,e.owner_id,CASE WHEN (e.starts_at AT TIME ZONE 'Asia/Jakarta')::date=(now() AT TIME ZONE 'Asia/Jakarta')::date THEN 'day_of' ELSE 'h_minus_1' END FROM public.calendar_events e WHERE e.status='active' AND (e.starts_at AT TIME ZONE 'Asia/Jakarta')::date IN ((now() AT TIME ZONE 'Asia/Jakarta')::date,(now() AT TIME ZONE 'Asia/Jakarta')::date+1) ON CONFLICT(event_id,recipient_id,kind) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.generate_event_reminders() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.generate_event_reminders() TO service_role;
CREATE INDEX calendar_scope_idx ON public.calendar_events(owner_id,starts_at);
CREATE INDEX activities_owner_date_idx ON public.sales_activities(owner_id,occurred_at);
CREATE POLICY it_work_update ON public.work_items FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'it')) WITH CHECK(public.has_role(auth.uid(),'it'));
CREATE POLICY it_lead_insert ON public.sales_leads FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'it'));
CREATE POLICY it_lead_update ON public.sales_leads FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'it')) WITH CHECK(public.has_role(auth.uid(),'it'));
CREATE POLICY it_event_update ON public.calendar_events FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'it')) WITH CHECK(public.has_role(auth.uid(),'it'));